const m = $('Retrieve Docs And Build Request').item.json;
const j = $json;
let txt = (j.content && j.content.parts && j.content.parts[0] && j.content.parts[0].text) || (j.content && j.content[0] && j.content[0].text) || j.text || j.output_text || (j.message && j.message.content) || '';
txt = String(txt).split('```json').join('').split('```').join('').trim();
let r; try { r = JSON.parse(txt); } catch (e) { r = { status: 'escalate', answer: '' }; }
const status = ['answered', 'escalate', 'refuse'].includes(r.status) ? r.status : 'escalate';
let answer = r.answer || '';
if (status === 'escalate') answer = "I'll pass this to the team. They will reply by email within 1 working day.";
if (status === 'refuse' && !answer) answer = "I can't give tax, legal or investment advice here. I can arrange a paid consultation with a qualified accountant.";
return { json: { question: m.question, status: status, answer: answer, sources: status === 'answered' ? (r.source_docs || m.sources) : [], logged_at: new Date().toISOString() } };
